// FUNÃ‡ÃƒO EXIGIDA PELO BUNDLE.JS
window.loadData = function(activeModule, onComplete) {
    console.log("[data.js] loadData called. Mounting VFS...");

    // 1. Configura o Module global para o Emscripten
    if (!window.Module) window.Module = activeModule;
    
    // 2. Define onde estÃ¡ o arquivo (Blob ou URL)
    var PACKAGE_NAME = '_framework/data/data.data';
    var PACKAGE_SIZE = 434393626;
    
    // OtimizaÃ§Ã£o: Se bundle.js jÃ¡ baixou e criou um blob, usa ele!
    if (typeof window.assetblob !== 'undefined' && window.assetblob) {
        console.log("[data.js] Using existing assetblob: " + window.assetblob);
        PACKAGE_NAME = window.assetblob;
    }

    // 3. FunÃ§Ã£o de carregamento (XHR)
    function fetchRemotePackage(packageName, packageSize, callback, errback) {
        var xhr = new XMLHttpRequest();
        xhr.open('GET', packageName, true);
        xhr.responseType = 'arraybuffer';
        
        xhr.onprogress = function(event) {
            var url = packageName;
            var size = packageSize;
            if (event.total) size = event.total;
            if (event.loaded) {
                if (!xhr.addedTotal) {
                    xhr.addedTotal = true;
                    if (!Module.dataFileDownloads) Module.dataFileDownloads = {};
                    Module.dataFileDownloads[url] = { loaded: event.loaded, total: size };
                } else {
                    Module.dataFileDownloads[url].loaded = event.loaded;
                }
                var total = 0;
                var loaded = 0;
                var num = 0;
                for (var download in Module.dataFileDownloads) {
                var data = Module.dataFileDownloads[download];
                total += data.total;
                loaded += data.loaded;
                num++;
                }
                total = Math.ceil(total * Module.expectedDataFileDownloads/num);
                if (Module['setStatus']) Module['setStatus']('Downloading game data... (' + loaded + '/' + total + ')');
            } else if (!Module.dataFileDownloads) {
                if (Module['setStatus']) Module['setStatus']('Downloading game data...');
            }
        };
        
        xhr.onerror = function(event) { throw new Error("NetworkError for: " + packageName); };
        
        xhr.onload = function(event) {
            if (xhr.status == 200 || xhr.status == 304 || xhr.status == 206 || (xhr.status == 0 && xhr.response)) {
                callback(xhr.response);
            } else {
                throw new Error(xhr.statusText + " : " + xhr.responseURL);
            }
        };
        xhr.send(null);
    }

    // 4. FunÃ§Ã£o de erro
    function handleError(err) {
        console.error('package error:', err);
    }

    // 5. FunÃ§Ã£o que cria os arquivos na memÃ³ria (VFS)
    function processPackageData(data) {
        var byteArray = new Uint8Array(data);
        var failed = 0;

        function mkdirp(path) {
            if (!path || path === "/" || Module.FS.analyzePath(path).exists) return;
            if (typeof Module.FS.mkdirTree === "function") {
                try {
                    Module.FS.mkdirTree(path, 493);
                    return;
                } catch (e) {
                    if (Module.FS.analyzePath(path).exists) return;
                }
            }
            var current = "";
            path.split("/").forEach(function(part) {
                if (!part) return;
                current += "/" + part;
                if (Module.FS.analyzePath(current).exists) return;
                Module.FS.mkdir(current, 493);
            });
        }

        package_metadata.forEach(function(file) {
            var dir = file.filename.substring(0, file.filename.lastIndexOf('/'));
            try { mkdirp(dir); } catch(e) { console.error("Error creating directory " + dir, e); failed++; }
        });
        
        package_metadata.forEach(function(file) {
            var fileData = byteArray.subarray(file.start, file.end);
            try {
                Module.FS.writeFile(file.filename, fileData, { canOwn: true });
            } catch(e) {
                failed++;
                console.error("Error creating file " + file.filename, e);
            }
        });

        if (failed) throw new Error("Packaged Celeste data failed to mount: " + failed + " filesystem errors");
        console.log("[data.js] VFS mounted successfully.");
        
        if (onComplete) onComplete();
    }

    // 6. Iniciar
    Module.addRunDependency('datafile_data.data');
    fetchRemotePackage(PACKAGE_NAME, PACKAGE_SIZE, function(data) {
        processPackageData(data);
        Module.removeRunDependency('datafile_data.data');
    }, handleError);
};
